func:
// Modbus register map (holding registers, 0-based)
// See firmware/codesys/GVL_MODBUS.st
//
// RW registers (HMI → PLC):
//   0  eOperatingMode  (0=MANUAL, 1=DT325_AUTO)
//   1  xHMI_CycleStart
//   2  xHMI_JogDown
//   3  xHMI_JogUp
//   4  xHMI_SonicToggle
//   5  xHMI_FaultReset
//   6-7 rTargetDepth_mm (IEEE 754 REAL, low word first)
//   8-9 rTargetFreq_Hz  (IEEE 754 REAL, low word first)
//
// RO registers (PLC → HMI):
//  10  eSystemState
//  11  eHubState
//  12  eSonicState
//  13-14 rPosition_mm  (REAL)
//  15-16 rActualFreq_Hz (REAL)
//  17-18 rActualCurrent_pct (REAL)
//  19  eSafetyReason
//  20  xSystemOK
//  21  iCycleCount

var regs = msg.payload;
if (!Array.isArray(regs) || regs.length < 22) { return null; }

function regsToReal(lo, hi) {
    var buf = Buffer.allocUnsafe(4);
    buf.writeUInt16BE(hi, 0);
    buf.writeUInt16BE(lo, 2);
    return buf.readFloatBE(0);
}

var SYS_STATE = ['IDLE','MANUAL','DT325_AUTO','FAULT','E-STOP'];
var HUB_STATE = ['IDLE','HOMING','DRILL_WAIT','DRILLING','STOP_SONIC','RETRACT','ESTOP_HOLD','FAULT'];
var SONIC_STATE = ['IDLE','STARTING','RUNNING','STOPPING','FAST_STOP','FAULT'];
var SAFETY_REASON = ['OK','ESTOP','LIMIT_UP','LIMIT_DOWN','HUB_ALARM','STONE_DETECTED','VFD_COMM'];

var d = {
    mode:         regs[0],
    systemState:  SYS_STATE[regs[10]]  || ('SYS_'+regs[10]),
    hubState:     HUB_STATE[regs[11]]  || ('HUB_'+regs[11]),
    sonicState:   SONIC_STATE[regs[12]] || ('SONIC_'+regs[12]),
    position_mm:  regsToReal(regs[13], regs[14]),
    freq_hz:      regsToReal(regs[15], regs[16]),
    current_pct:  regsToReal(regs[17], regs[18]),
    safetyReason: SAFETY_REASON[regs[19]] || ('SAFETY_'+regs[19]),
    systemOK:     regs[20] !== 0,
    cycleCount:   regs[21],
    ts:           new Date().toLocaleTimeString('de-AT')
};

// Store for downstream nodes
flow.set('plc', d);

return { payload: d };

var d = msg.payload;
return [
    { payload: d.position_mm },
    { payload: d.freq_hz },
    { payload: d.current_pct },
    { payload: (d.systemOK ? '✅ OK' : '❌ ' + d.safetyReason), color: d.systemOK ? 'green' : 'red' },
    { payload: d.systemState + ' / ' + d.hubState + ' / ' + d.sonicState },
    { payload: d.cycleCount },
    { payload: d }
];

node.status({fill:'red',shape:'ring',text:'PLC Verbindung verloren!'});
flow.set('plc', null);
return { payload: '⚠️ Keine Verbindung zur SPS' };

var d = msg.payload;
if (!d.systemOK) {
    var alarm = {
        ts: new Date().toISOString(),
        reason: d.safetyReason,
        hub: d.hubState,
        sonic: d.sonicState
    };
    node.warn('ALARM: ' + JSON.stringify(alarm));
    return { payload: alarm, topic: 'vibrocore/alarm' };
}
return null;

// Write xHMI_CycleStart = 1 (register 1)
// The PLC will reset it after processing the rising edge
return { payload: [1], topic: 'write', fc: 6, unitid: 1, address: 1 };

// Momentary jog: never latch. PLC watchdog stops motion if heartbeat stalls > 300 ms.
var dir = msg.topic;
var pressed = msg.payload ? 1 : 0;
if (dir === 'jog_down') {
    flow.set('jog_down', pressed);
    if (pressed) { flow.set('jog_up', 0); }
} else if (dir === 'jog_up') {
    flow.set('jog_up', pressed);
    if (pressed) { flow.set('jog_down', 0); }
}
if (!pressed && !flow.get('jog_down') && !flow.get('jog_up')) {
    // Immediate clear of direction bits; heartbeat inject also clears when idle.
    node.send({ payload: [0], fc: 6, unitid: 1, address: 2 });
    node.send({ payload: [0], fc: 6, unitid: 1, address: 3 });
}
return null;

// While a jog button is held, refresh direction bits and bump heartbeat (%MW33).
// PLC clears jog if iHMI_JogHeartbeat does not change for > 300 ms.
var down = flow.get('jog_down') || 0;
var up = flow.get('jog_up') || 0;
var hb = (flow.get('jog_hb') || 0) + 1;
if (hb > 65535) { hb = 1; }
flow.set('jog_hb', hb);

var out = [];
out.push({ payload: [down ? 1 : 0], fc: 6, unitid: 1, address: 2 });
out.push({ payload: [up ? 1 : 0], fc: 6, unitid: 1, address: 3 });
out.push({ payload: [hb], fc: 6, unitid: 1, address: 33 });
return [out[0], out[1], out[2]];

// Write REAL (IEEE 754) to registers 6-7
// WAGO CODESYS Modbus Slave maps REAL as [lo_word, hi_word]
var buf = Buffer.allocUnsafe(4);
buf.writeFloatBE(msg.payload, 0);
var hi = buf.readUInt16BE(0);
var lo = buf.readUInt16BE(2);
return { payload: [lo, hi], fc: 16, unitid: 1, address: 6 };

var buf = Buffer.allocUnsafe(4);
buf.writeFloatBE(msg.payload, 0);
var hi = buf.readUInt16BE(0);
var lo = buf.readUInt16BE(2);
return { payload: [lo, hi], fc: 16, unitid: 1, address: 8 };

var d = msg.payload;
var row = [
    d.ts || new Date().toISOString(),
    (d.depth_mm || 0).toFixed(0) + ' mm',
    (d.freq_hz  || 0).toFixed(1) + ' Hz',
    (d.lat  || 0).toFixed(6),
    (d.lon  || 0).toFixed(6),
    d.signed ? '✅' : '⏳'
].join('  |  ');
return { payload: row };

// Send default target depth (1200 mm) and freq (100 Hz) to PLC on startup
var depthBuf = Buffer.allocUnsafe(4);
depthBuf.writeFloatBE(1200.0, 0);
var freqBuf = Buffer.allocUnsafe(4);
freqBuf.writeFloatBE(100.0, 0);

node.send([
    { payload: [depthBuf.readUInt16BE(2), depthBuf.readUInt16BE(0)], fc: 16, unitid: 1, address: 6 },
    null
]);
node.send([
    null,
    { payload: [freqBuf.readUInt16BE(2), freqBuf.readUInt16BE(0)], fc: 16, unitid: 1, address: 8 }
]);
return null;
